def transform(grid):
    # Enclosed outlined panels are filled with diagonal checker patterns; scattered markers specify pattern color.
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Find rectangular hollow frames of a color, by bounding box connected frame cells.
    from collections import deque
    seen=set(); frames=[]
    for y in range(h):
      for x in range(w):
        c=g[y][x]
        if c==0 or (y,x) in seen: continue
        q=[(y,x)]; seen.add((y,x)); comp=[]
        while q:
          a,b=q.pop(); comp.append((a,b))
          for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            aa,bb=a+da,b+db
            if 0<=aa<h and 0<=bb<w and g[aa][bb]==c and (aa,bb) not in seen:
              seen.add((aa,bb));q.append((aa,bb))
        ys=[a for a,b in comp];xs=[b for a,b in comp]
        y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        if y1-y0>=2 and x1-x0>=2 and all((a in (y0,y1) or b in (x0,x1)) for a,b in comp):
          # ensure complete rectangular border
          if all(g[y0][x]==c and g[y1][x]==c for x in range(x0,x1+1)) and all(g[y][x0]==c and g[y][x1]==c for y in range(y0,y1+1)):
            frames.append((y0,y1,x0,x1,c))
    # In demo, isolated 3s and 6s are markers: inner fill color is marker color, usually distinct from border.
    markers=[]
    for y in range(h):
      for x in range(w):
        if g[y][x] not in (0,) and not any(y in (a,b) or x in (c,d) for a,b,c,d,_ in frames):
          markers.append((y,x,g[y][x]))
    # use marker whose color is not frame colors, nearest frame; each frame gets diagonal pattern matching its marker
    for y0,y1,x0,x1,c in frames:
      candidates=[(abs(y-y0)+abs(x-x0),y,x,m) for y,x,m in markers if m!=c]
      if not candidates: continue
      _,_,_,m=min(candidates)
      for y in range(y0+1,y1):
        for x in range(x0+1,x1):
          if (y-y0 + x-x0)%2==0: g[y][x]=m
          else: g[y][x]=0
    # Remove all isolated markers/noise; background all outside frames.
    for y in range(h):
      for x in range(w):
        if not any(y0<=y<=y1 and x0<=x<=x1 for y0,y1,x0,x1,_ in frames): g[y][x]=0
    return g
