 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out-3/play/users/u015/system/state/workspace/programs/task-9d091b54.py",
 "content": "def transform(grid):
    g=[r[:] for r in grid]; h,w=len(g),len(g[0]); seen=set(); frames=[]
    for y in range(h):
      for x in range(w):
        c=g[y][x]
        if not c or (y,x) in seen: continue
        q=[(y,x)];seen.add((y,x));comp=[]
        while q:
          a,b=q.pop();comp.append((a,b))
          for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            aa,bb=a+da,b+db
            if 0<=aa<h and 0<=bb<w and g[aa][bb]==c and (aa,bb) not in seen:seen.add((aa,bb));q.append((aa,bb))
        ys=[a for a,b in comp];xs=[b for a,b in comp];y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
        if y1>y0 and x1>x0 and all(a in (y0,y1) or b in (x0,x1) for a,b in comp) and all(g[y0][xx]==c and g[y1][xx]==c for xx in range(x0,x1+1)) and all(g[yy][x0]==c and g[yy][x1]==c for yy in range(y0,y1+1)):
          frames.append((y0,y1,x0,x1,c))
    fcells={(y,x) for a,b,c,d,_ in frames for y in range(a,b+1) for x in range(c,d+1)}
    markers=[(y,x,grid[y][x]) for y in range(h) for x in range(w) if grid[y][x] and (y,x) not in fcells]
    for y0,y1,x0,x1,c in frames:
      _,_,_,fill=min((max(y0-y,0,y-y1)+max(x0-x,0,x-x1),y,x,m) for y,x,m in markers)
      for y in range(y0+1,y1):
        for x in range(x0+1,x1):
          g[y][x]=fill if (y-y0+x-x0)%2==0 else 0
    for y in range(h):
      for x in range(w):
        if (y,x) not in fcells:g[y][x]=0
    return g
